const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));const money=n=>'₹'+Math.round(Number(n)||0).toLocaleString('en-IN');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const byOutlet=id=>OUTLETS.find(o=>o.id===id);const filtered=(arr,key='outlet')=>state.outlet==='ALL'?arr:arr.filter(x=>x[key]===state.outlet);const save=(key,value)=>localStorage.setItem(LS+key,JSON.stringify(value));const currentOutlet=()=>state.outlet==='ALL'?'BH':state.outlet;
function toast(msg,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toastStack').append(el);setTimeout(()=>el.remove(),3800)}
function badge(text,tone=''){return `<span class="pill ${tone}">${esc(text)}</span>`}function channelBadge(c){let cls=c==='Swiggy'?'swiggy':c==='Zomato'?'zomato':c==='Dine-in'?'dine':'direct';return `<span class="channel ${cls}">${esc(c)}</span>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function card(title,subtitle,body,action=''){return `<section class="card"><div class="card-head"><div><div class="card-title">${title}</div>${subtitle?`<div class="card-subtitle">${subtitle}</div>`:''}</div>${action}</div>${body}</section>`}
function hasAccess(p){if(state.role===ROLES[0])return true;if(state.role===ROLES[1])return ['overview','orders','pos','menu','inventory','customers','people','finance'].includes(p);if(state.role===ROLES[2])return ['overview','menu','inventory','orders'].includes(p);return ['orders','pos','customers'].includes(p)}
function updateChrome(){const outlet=$('#outletSelect');outlet.value=state.outlet;$('#pageCrumb').textContent=PAGES[state.page]||'Overview';$('#sidebarRole').textContent=state.role;$('#topRole').textContent=state.role.split(' / ')[0];$$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.hidden=!hasAccess(b.dataset.page)});$('#newOrderCount').textContent=filtered(state.orders).filter(o=>o.status==='New').length;}
function render(){if(!hasAccess(state.page))state.page='overview';updateChrome();const views={overview:renderOverview,orders:renderOrders,pos:renderPOS,menu:renderMenu,inventory:renderInventory,customers:renderCustomers,people:renderPeople,finance:renderFinance,settings:renderSettings};$('#pageArea').innerHTML=views[state.page]();}
function scopedMoney(source){return filtered(source).reduce((a,x)=>a+(Number(x.amount)||Number(x.total)||0),0)}
